"""Device-side state access for the Android OpenDriver tasks.

OpenDriver is a client of an HTTP service: the application authenticates once
and then reads its own profile, rides, payments and support tickets from that
service.  The durable record of what happened therefore lives in the service,
not in the application, so a judgement reads the service through the same
read-only endpoints the application uses.

The request's own credential is taken from the application's WebView storage --
the same credential the application is using -- rather than being supplied by
the evaluator, so a judgement can only see what the signed-in account can see.
"""

from __future__ import annotations

import json
import re
from typing import Any, Mapping, Sequence
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

from evaluators.cua_review.platforms.android.webview_devtools import WebViewDevTools

#: Application identifier of OpenDriver on the device.
DEFAULT_APP_PACKAGE = "com.killt.opendriver"

#: Address the device reaches its OpenDriver service on.  The emulator maps the
#: host's loopback to ``10.0.2.2``, which is where the service is reached from.
DEFAULT_API_BASE_URL = "http://10.0.2.2:4321"

#: How long one endpoint request may take.
REQUEST_TIMEOUT_SECONDS = 30.0

#: Storage-key name patterns, in order of preference, that hold the credential
#: the application presents to its service.
TOKEN_KEY_PATTERNS = (
    r"opendriver\..*token",
    r"opendriver\.localState\.",
    r".*\.accessToken",
    r".*\.authToken",
    r".*auth.*",
)

#: Keys inside a stored JSON document that carry the credential.
TOKEN_FIELD_NAMES = (
    "accessToken",
    "authToken",
    "token",
    "access_token",
    "auth_token",
    "idToken",
    "jwt",
)


def normalize_text(value: Any) -> str:
    """Collapse whitespace in *value* and return it as text.

    Screen text arrives with the line breaks and padding the renderer chose;
    comparisons care about the words, not the layout.
    """
    if value is None:
        return ""
    return " ".join(str(value).split()).strip()


def flatten_text(value: Any) -> str:
    """Render a nested structure as one text blob for substring comparison.

    Keys and values are both included, because a value that matters is often
    identified only by the name of the field holding it.  The result is
    unbounded in length but not in content: nothing is added that was not
    already present in the structure.
    """
    parts: list[str] = []

    def walk(node: Any) -> None:
        if node is None or isinstance(node, bool):
            return
        if isinstance(node, Mapping):
            for key, item in node.items():
                parts.append(str(key))
                walk(item)
            return
        if isinstance(node, (list, tuple, set)):
            for item in node:
                walk(item)
            return
        text = str(node).strip()
        if text:
            parts.append(text)

    walk(value)
    return " ".join(parts)


def read_accessibility_text(controller: Any) -> str:
    """Return the visible text of the device's current screen.

    Both the node text and the content description are collected: an icon-only
    control carries its label in the description, and a task may require either.
    """
    if controller is None or not hasattr(controller, "execute_adb"):
        raise RuntimeError("an adb-capable controller is required to read the screen")
    xml_text = ""
    try:
        xml_text = str(
            controller.execute_adb(["exec-out", "uiautomator", "dump", "/dev/tty"]) or ""
        )
    except Exception:
        xml_text = ""
    if "<hierarchy" not in xml_text:
        remote = "/sdcard/window_dump.xml"
        controller.execute_adb(["shell", "uiautomator", "dump", remote])
        xml_text = str(controller.execute_adb(["exec-out", "cat", remote]) or "")
    texts: list[str] = []
    for attribute in ("text", "content-desc"):
        for match in re.finditer(rf'{attribute}="([^"]*)"', xml_text):
            value = normalize_text(match.group(1))
            if value:
                texts.append(value)
    return "\n".join(dict.fromkeys(texts))


def read_foreground_window(controller: Any) -> str:
    """Return the lines of the window dump that name the focused activity.

    Which application owns the focused window is the one part of the screen the
    accessibility tree does not carry, so it is read from the window dump.
    """
    if controller is None or not hasattr(controller, "execute_adb"):
        raise RuntimeError("an adb-capable controller is required to read the window state")
    output = str(controller.execute_adb(["shell", "dumpsys", "window"]) or "")
    return "\n".join(
        line.strip()
        for line in output.splitlines()
        if "mCurrentFocus" in line or "mFocusedApp" in line
        or "topResumedActivity" in line
    )


def screen_tokens(controller: Any) -> set[str]:
    """Return the normalized text tokens of the device's current screen."""
    return {
        normalize_text(line).casefold()
        for line in read_accessibility_text(controller).splitlines()
        if normalize_text(line)
    }


def _credential_from_document(document: Any) -> str:
    """Find a credential inside a decoded storage document."""
    if isinstance(document, str):
        try:
            document = json.loads(document)
        except json.JSONDecodeError:
            return document.strip() if len(document.strip()) > 20 else ""
    if not isinstance(document, Mapping):
        return ""
    for name in TOKEN_FIELD_NAMES:
        value = document.get(name)
        if isinstance(value, str) and value.strip():
            return value.strip()
    for key, value in document.items():
        if isinstance(value, Mapping):
            found = _credential_from_document(value)
            if found:
                return found
        elif isinstance(value, str) and value.strip() and "token" in str(key).lower():
            return value.strip()
    return ""


def read_app_credential(controller: Any, app_package: str) -> str:
    """Return the credential the application presents to its service.

    The application's own storage is searched, so the credential is the one the
    application is actually using rather than one supplied out of band.
    """
    devtools = WebViewDevTools(controller, app_package)
    for pattern in TOKEN_KEY_PATTERNS:
        try:
            stored = devtools.read_matching_keys(pattern)
        except Exception:
            continue
        for key, raw in stored.items():
            if "token" in key.lower() and raw.strip() and len(raw.strip()) > 20:
                return raw.strip()
            found = _credential_from_document(raw)
            if found:
                return found
    raise RuntimeError(
        f"the {app_package} storage carries no service credential"
    )


def _fetch_json(url: str, token: str = "") -> tuple[str, Any]:
    """Request one endpoint and return ``(status, decoded_body)``."""
    headers = {"Accept": "application/json"}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    request = Request(url, headers=headers, method="GET")
    try:
        with urlopen(request, timeout=REQUEST_TIMEOUT_SECONDS) as response:
            body = response.read().decode("utf-8", errors="replace")
            status = f"HTTP {response.status}"
    except HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        status = f"HTTP {exc.code}"
    except URLError as exc:
        return f"unreachable: {exc.reason}", ""
    try:
        return status, json.loads(body)
    except json.JSONDecodeError:
        return status, body


def read_public_backend_snapshot(
    paths: Sequence[str], *, api_base_url: str = DEFAULT_API_BASE_URL
) -> dict[str, Any]:
    """Read a set of endpoints that need no credential.

    Used where the account's own credential is not required to observe the
    state under test.  Each response is recorded with the path that produced it,
    the status it returned and its decoded body, so a judgement can state what
    it saw even when an endpoint answers with an error.
    """
    base = str(api_base_url or DEFAULT_API_BASE_URL).rstrip("/")
    responses: dict[str, Any] = {}
    for path in paths:
        path = str(path or "").strip()
        if not path:
            continue
        status, body = _fetch_json(f"{base}/{path.lstrip('/')}")
        responses[path] = {"status": status, "data": body}
    return {"api_base_url": base, "responses": responses, "authenticated": False}


def read_backend_snapshot(
    controller: Any,
    *,
    app_package: str = DEFAULT_APP_PACKAGE,
    api_base_url: str = DEFAULT_API_BASE_URL,
    paths: Sequence[str] | None = None,
) -> dict[str, Any]:
    """Read the application's own record from its service, read-only.

    The credential is taken from the application, every request is a ``GET``,
    and no request changes anything on either side.
    """
    base = str(api_base_url or DEFAULT_API_BASE_URL).rstrip("/")
    token = read_app_credential(controller, app_package)
    requested = list(paths) if paths else _default_paths()
    responses: dict[str, Any] = {}
    for path in requested:
        status, body = _fetch_json(f"{base}/{str(path).lstrip('/')}", token)
        responses[str(path)] = {"status": status, "data": body}
    return {
        "api_base_url": base,
        "app_package": app_package,
        "app_credential_present": bool(token),
        "responses": responses,
        "authenticated": True,
    }


